result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/stairs.js", "content": "import * as THREE from 'three';

/**
 * Build a spiral staircase as a THREE.Group.
 *
 * The group contains:
 *  - a center column cylinder (name: "column") of radius `innerRadius`
 *    spanning y in [0, totalHeight]
 *  - `steps` box steps (names: "step-0" ... "step-{steps-1}"), where step i
 *    is positioned at angle i * stepArcDeg around the Y axis, its center at
 *    height (i + 0.5) * totalHeight / steps, extending radially from
 *    `innerRadius` to `innerRadius + stepWidth`, rotated so its long
 *    (radial) edge is tangent to the spiral. Step thickness equals the rise
 *    (totalHeight / steps), which guarantees consecutive steps never
 *    overlap vertically.
 *
 * @param {object} opts
 * @param {number} [opts.steps=16]        number of steps
 * @param {number} [opts.totalHeight=3]   total height of the staircase
 * @param {number} [opts.innerRadius=0.2] radius of the center column
 * @param {number} [opts.stepWidth=0.8]   radial extent of each step
 * @param {number} [opts.stepArcDeg=22.5] angular increment per step (degrees)
 * @returns {THREE.Group}
 */
export function buildStairs({
  steps = 16,
  totalHeight = 3,
  innerRadius = 0.2,
  stepWidth = 0.8,
  stepArcDeg = 22.5,
} = {}) {
  const group = new THREE.Group();
  const rise = totalHeight / steps;

  // Center column.
  const column = new THREE.Mesh(
    new THREE.CylinderGeometry(innerRadius, innerRadius, totalHeight, 32)
  );
  column.name = 'column';
  column.position.y = totalHeight / 2;
  group.add(column);

  // Tangential depth of a step: chord spanning the arc at the outer edge,
  // slightly shortened so adjacent boxes do not intersect horizontally.
  const arcRad = THREE.MathUtils.degToRad(stepArcDeg);
  const outerRadius = innerRadius + stepWidth;
  const depth = Math.max(2 * outerRadius * Math.sin(arcRad / 2) * 0.9, 1e-4);

  for (let i = 0; i < steps; i++) {
    // Box: x = radial extent, y = thickness (one rise), z = tangential depth.
    const geometry = new THREE.BoxGeometry(stepWidth, rise, depth);
    // Shift so the box spans x in [innerRadius, innerRadius + stepWidth].
    geometry.translate(innerRadius + stepWidth / 2, 0, 0);

    const step = new THREE.Mesh(geometry);
    step.name = `step-${i}`;
    step.position.y = (i + 0.5) * rise;
    step.rotation.y = -THREE.MathUtils.degToRad(i * stepArcDeg);

    step.userData = {
      index: i,
      angleDeg: i * stepArcDeg,
      y: step.position.y,
      rise,
      thickness: rise,
    };

    group.add(step);
  }

  return group;
}

/**
 * Return the pose of step `i` within a group built by {@link buildStairs}.
 *
 * @param {THREE.Group} group
 * @param {number} i    zero-based step index
 * @returns {{angleDeg: number, y: number}}
 */
export function stepPose(group, i) {
  const step = group.getObjectByName(`step-${i}`);
  if (!step) {
    throw new Error(`No step with index ${i} in group`);
  }
  return { angleDeg: step.userData.angleDeg, y: step.userData.y };
}
"})
