result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/stairs.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildStairs, stepPose } from '../src/stairs.js';

const opts = {
  steps: 16,
  totalHeight: 3.2,
  innerRadius: 0.25,
  stepWidth: 0.8,
  stepArcDeg: 22.5,
};

const rise = opts.totalHeight / opts.steps;
// Tolerance derived from the rise so float noise never fails the checks.
const tol = rise * 1e-9;

function stepMeshes(group) {
  return group.children.filter((c) => c.name.startsWith('step-'));
}

describe('buildStairs', () => {
  const group = buildStairs(opts);
  group.updateMatrixWorld(true);

  it('has a center column', () => {
    const column = group.getObjectByName('column');
    expect(column).toBeDefined();
  });

  it('contains exactly `steps` step meshes', () => {
    expect(stepMeshes(group).length).toBe(opts.steps);
  });

  it('places step i at angle i * stepArcDeg', () => {
    for (let i = 0; i < opts.steps; i++) {
      const pose = stepPose(group, i);
      expect(pose.angleDeg).toBeCloseTo(i * opts.stepArcDeg, 9);
    }
  });

  it('positions the last step at angle 337.5 deg (within 1e-9)', () => {
    const last = opts.steps - 1;
    const { angleDeg } = stepPose(group, last);
    expect(Math.abs(angleDeg - 337.5)).toBeLessThan(1e-9);
  });

  it('centers the last step at totalHeight minus half a rise', () => {
    // y_last = (steps - 1 + 0.5) * rise = totalHeight - rise / 2
    //       = 15/16 * totalHeight + rise/2 ... equivalently one half-rise
    // below the very top of the staircase.
    const last = opts.steps - 1;
    const { y } = stepPose(group, last);
    expect(Math.abs(y - (opts.totalHeight - rise / 2))).toBeLessThan(1e-9);
  });

  it('never overlaps consecutive steps vertically', () => {
    // Each step is one rise thick, centered at (i + 0.5) * rise, so
    // top of step i == bottom of step i+1 exactly (up to float error).
    for (let i = 0; i < opts.steps - 1; i++) {
      const topI = stepPose(group, i).y + rise / 2;
      const bottomNext = stepPose(group, i + 1).y - rise / 2;
      expect(topI).toBeLessThanOrEqual(bottomNext + tol);
    }
  });

  it('keeps all step geometry within [innerRadius, innerRadius + stepWidth] radially', () => {
    const minR = opts.innerRadius - tol;
    const maxR = opts.innerRadius + opts.stepWidth + tol;
    for (const mesh of stepMeshes(group)) {
      const pos = mesh.geometry.attributes.position;
      const v = new THREE.Vector3();
      for (let k = 0; k < pos.count; k++) {
        v.fromBufferAttribute(pos, k).applyMatrix4(mesh.matrixWorld);
        const r = Math.hypot(v.x, v.z);
        expect(r).toBeGreaterThanOrEqual(minR);
        expect(r).toBeLessThanOrEqual(maxR);
      }
    }
  });

  it('stepPose throws for an out-of-range index', () => {
    expect(() => stepPose(group, opts.steps)).toThrow();
    expect(() => stepPose(group, -1)).toThrow();
  });
});
"})
